class MDEObjectBuilder extends fb.ObjectBuilder {
  final MDEDetectOptionsObjectBuilder? _DETECT_OPTIONS;
  final MDEDetectReportObjectBuilder? _DETECT_REPORT;
  final MDECompareOptionsObjectBuilder? _COMPARE_OPTIONS;
  final MDECompareReportObjectBuilder? _COMPARE_REPORT;
  final MDEScoreOptionsObjectBuilder? _SCORE_OPTIONS;
  final MDEScoreReportObjectBuilder? _SCORE_REPORT;

  MDEObjectBuilder({
    MDEDetectOptionsObjectBuilder? DETECT_OPTIONS,
    MDEDetectOptionsObjectBuilder? detectOptions,
    MDEDetectReportObjectBuilder? DETECT_REPORT,
    MDEDetectReportObjectBuilder? detectReport,
    MDECompareOptionsObjectBuilder? COMPARE_OPTIONS,
    MDECompareOptionsObjectBuilder? compareOptions,
    MDECompareReportObjectBuilder? COMPARE_REPORT,
    MDECompareReportObjectBuilder? compareReport,
    MDEScoreOptionsObjectBuilder? SCORE_OPTIONS,
    MDEScoreOptionsObjectBuilder? scoreOptions,
    MDEScoreReportObjectBuilder? SCORE_REPORT,
    MDEScoreReportObjectBuilder? scoreReport,
  })
      : _DETECT_OPTIONS = detectOptions ?? DETECT_OPTIONS,
        _DETECT_REPORT = detectReport ?? DETECT_REPORT,
        _COMPARE_OPTIONS = compareOptions ?? COMPARE_OPTIONS,
        _COMPARE_REPORT = compareReport ?? COMPARE_REPORT,
        _SCORE_OPTIONS = scoreOptions ?? SCORE_OPTIONS,
        _SCORE_REPORT = scoreReport ?? SCORE_REPORT;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? DETECT_OPTIONSOffset = _DETECT_OPTIONS?.getOrCreateOffset(fbBuilder);
    final int? DETECT_REPORTOffset = _DETECT_REPORT?.getOrCreateOffset(fbBuilder);
    final int? COMPARE_OPTIONSOffset = _COMPARE_OPTIONS?.getOrCreateOffset(fbBuilder);
    final int? COMPARE_REPORTOffset = _COMPARE_REPORT?.getOrCreateOffset(fbBuilder);
    final int? SCORE_OPTIONSOffset = _SCORE_OPTIONS?.getOrCreateOffset(fbBuilder);
    final int? SCORE_REPORTOffset = _SCORE_REPORT?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(6);
    fbBuilder.addOffset(0, DETECT_OPTIONSOffset);
    fbBuilder.addOffset(1, DETECT_REPORTOffset);
    fbBuilder.addOffset(2, COMPARE_OPTIONSOffset);
    fbBuilder.addOffset(3, COMPARE_REPORTOffset);
    fbBuilder.addOffset(4, SCORE_OPTIONSOffset);
    fbBuilder.addOffset(5, SCORE_REPORTOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
